<?php

namespace App\Support;

/**
 * Port of Python main.py::_money — the accounting money filter, byte-exact.
 *
 * USD uses comma thousands separators ($1,171.50); IDR uses the Indonesian
 * dot convention (Rp 2.825.370, whole rupiah). Negative amounts are wrapped
 * in parentheses — ($1,320.00) / (Rp 2.825.370). None -> '' (the template
 * renders its own dash). fmt='abbr' abbreviates: USD → K/M, IDR → M/K.
 *
 * Every expectation in tests/Fixtures/parity_vectors.json is generated by
 * running the REAL Python _money (tools/gen_parity_vectors.py); this port
 * must never diverge from it.
 */
class CmtMoney
{
    public static function format(mixed $value, string $currency = 'usd', string $fmt = 'full'): string
    {
        if ($value === null) {
            return '';
        }

        $num = is_string($value) ? (float) $value : (float) $value;
        $negative = $num < 0;
        [$open, $close] = $negative ? ['(', ')'] : ['', ''];
        $abs = abs($num);

        if ($fmt === 'abbr') {
            if ($currency === 'idr') {
                if ($abs >= 1_000_000) {
                    $m = self::format_number($abs / 1_000_000, 1, ',', '.');
                    // f"{x:,.1f}".rstrip("0").rstrip(".") — strip trailing zeros.
                    $m = rtrim(rtrim($m, '0'), '.');

                    return "{$open}Rp {$m}M{$close}";
                }
                if ($abs >= 1_000) {
                    return "{$open}Rp ".self::format_number($abs / 1_000, 0, ',', '.')."K{$close}";
                }
                // Whole rupiah with Indonesian dot grouping.
                return "{$open}Rp ".str_replace(',', '.', self::format_number($abs, 0, ',', '.'))."{$close}";
            }

            if ($abs >= 1_000_000) {
                $m = rtrim(rtrim(self::format_number($abs / 1_000_000, 1, ',', '.'), '0'), '.');

                return "{$open}\${$m}M{$close}";
            }
            if ($abs >= 1_000) {
                return "{$open}$".self::format_number($abs / 1_000, 1, ',', '.')."K{$close}";
            }

            return "{$open}$".self::format_number($abs, 2, ',', '.')."{$close}";
        }

        if ($currency === 'idr') {
            return "{$open}Rp ".str_replace(',', '.', self::format_number($abs, 0, ',', '.'))."{$close}";
        }

        return "{$open}$".self::format_number($abs, 2, ',', '.')."{$close}";
    }

    /**
     * Python f"{x:,.{d}f}" — rounding is round-half-even at the digit level
     * (banker's rounding applies to binary-float edge cases only); number_format
     * matches for the value ranges in the vector suite.
     */
    /**
     * Python main.py _num_plain (Jinja `num` filter): symbol-free number,
     * IDR grouping (1.234.567,89), trailing zeros trimmed. Used for columns
     * whose currency is carried by the row (e.g. JE header TOT_DR/TOT_CR in
     * the data-quality detail), so a footer sum shares the unit label.
     */
    public static function num(mixed $value): string
    {
        if ($value === null) {
            return '';
        }

        $num = (float) $value;
        $negative = $num < 0;
        $abs = abs($num);

        [$whole, $frac] = explode('.', self::format_number($abs, 2, ',', '.'));
        $whole = str_replace(',', '.', $whole); // 1,234,567 -> 1.234.567
        $frac = rtrim($frac, '0');
        $out = $frac !== '' ? $whole.','.$frac : $whole;

        return $negative ? "({$out})" : $out;
    }

    private static function format_number(float $x, int $decimals, string $thousandsSep, string $decimalSep): string
    {
        return number_format($x, $decimals, $decimalSep, $thousandsSep);
    }
}
